/**
 * 点单词浮出的轻量词典卡片。
 *
 * 只管一件事：这个词是什么意思 —— 发音、词性、中文义、英文释义、搭配、例句。
 * 「它在这一段里为什么这样用」交给右侧的 AI 面板（卡片里留一个入口），
 * 所以点词本身不会触发 AI 请求，读起来是轻的。
 */
import {
  Bookmark,
  BookmarkPlus,
  LoaderCircle,
  Sparkles,
  Volume2,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { LanguageInsight } from "@leafia/shared";
import { fallbackInsight } from "../../data/demo";
import { api } from "../../lib/api";
import { cn } from "../../lib/cn";
import { speakEnglish } from "../../lib/speak";
import { useReaderActions } from "./useReaderActions";
import "./word-lookup-folder.css";

export interface WordLookupFolderProps {
  word: string;
  contextBefore: string;
  contextAfter: string;
  x: number;
  y: number;
  drawer: boolean;
  bookId: string;
  bookLabel: string;
  /**
   * 打开右侧 AI 面板，解释这个词在上下文里的用法。
   * 不传就表示这处没有 AI 面板（比如练习页），卡片上那一格也收起来 ——
   * 词典管「这个词是什么意思」，这句上下文为什么这么用是另一件事。
   */
  onExplain?: (
    word: string,
    contextBefore: string,
    contextAfter: string,
  ) => void;
  onClose: () => void;
}

export function WordLookupFolder({
  word,
  contextBefore,
  contextAfter,
  x,
  y,
  drawer,
  bookId,
  bookLabel,
  onExplain,
  onClose,
}: WordLookupFolderProps) {
  const panelRef = useRef<HTMLElement>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<LanguageInsight | null>(null);
  const { addToReview, saveKnowledgeCard, addToCorpus } = useReaderActions({
    bookId,
    bookLabel,
  });

  const requestKey = useMemo(() => `${word}:${bookId}`, [bookId, word]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setResult(null);

    void api
      .dictionary(word)
      .then((response) => response.insight)
      .catch(() => fallbackInsight(word))
      .then((next) => {
        if (!cancelled) setResult(next);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [requestKey, word]);

  useEffect(() => {
    const onPointerDown = (event: PointerEvent) => {
      if (
        panelRef.current &&
        !panelRef.current.contains(event.target as Node)
      ) {
        onClose();
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [onClose]);

  return createPortal(
    <aside
      ref={panelRef}
      className={cn(
        "word-lookup-folder",
        drawer && "word-lookup-folder--drawer",
      )}
      style={drawer ? undefined : { left: x, top: y }}
      role="dialog"
      aria-label={`${word} 的词典卡片`}
    >
      <span className="word-lookup-folder__back" aria-hidden="true" />
      <span className="word-lookup-folder__paper" aria-hidden="true" />
      <div className="word-lookup-folder__front">
        <header>
          <div>
            <small>词典</small>
            <strong>{word}</strong>
            {result?.pronunciation ? (
              <span className="word-lookup-folder__pronunciation">
                {result.pronunciation}
              </span>
            ) : null}
          </div>
          <div className="word-lookup-folder__header-actions">
            <button
              type="button"
              aria-label={`朗读 ${word}`}
              onClick={() => speakEnglish(word)}
            >
              <Volume2 size={15} />
            </button>
            <button type="button" onClick={onClose} aria-label="关闭词典卡片">
              <X size={15} />
            </button>
          </div>
        </header>

        <div className="word-lookup-folder__result">
          {loading ? (
            <span className="word-lookup-folder__loading">
              <LoaderCircle size={16} />
              正在查询…
            </span>
          ) : result ? (
            <>
              <div className="word-lookup-folder__meaning">
                <strong>{result.meaningsZh.join("；")}</strong>
                <p>{result.definitionEn}</p>
                {(result.partOfSpeech || result.cefr) && (
                  <span className="word-lookup-folder__tags">
                    {[result.partOfSpeech, result.cefr]
                      .filter(Boolean)
                      .map((tag) => (
                        <em key={tag}>{tag}</em>
                      ))}
                  </span>
                )}
              </div>
              {result.collocations.length > 0 && (
                <div className="word-lookup-folder__chips">
                  {result.collocations.slice(0, 4).map((item) => (
                    <span key={item}>{item}</span>
                  ))}
                </div>
              )}
              {result.examples[0] && (
                <blockquote>
                  {result.examples[0].text}
                  {result.examples[0].translationZh && (
                    <small>{result.examples[0].translationZh}</small>
                  )}
                </blockquote>
              )}
            </>
          ) : (
            <span>暂时没有结果。</span>
          )}
        </div>

        {onExplain && (
          <button
            type="button"
            className="word-lookup-folder__ai"
            onClick={() => onExplain(word, contextBefore, contextAfter)}
          >
            <Sparkles size={14} />
            <span>
              <strong>AI 语境解读</strong>
              <small>它在这一段里为什么这样用</small>
            </span>
          </button>
        )}

        <footer>
          <button
            type="button"
            className="is-primary"
            onClick={() => result && addToReview(result, contextBefore)}
            disabled={!result}
          >
            <Bookmark size={14} />
            收藏到单词本
          </button>
          <button
            type="button"
            disabled={!result}
            onClick={() =>
              result &&
              void saveKnowledgeCard({
                term: word,
                contextBefore,
                contextAfter,
                insight: result,
              })
            }
          >
            <BookmarkPlus size={14} />
            存知识卡
          </button>
          <button
            type="button"
            disabled={!result}
            onClick={() => result && void addToCorpus(result)}
          >
            加入语料
          </button>
        </footer>
      </div>
    </aside>,
    document.body,
  );
}
